def count_numbers_over_10_start_end_odd():
    """
    Counts integers greater than 10 that start and end with odd digits.
    Returns a dictionary with:
    - 'count': total count of such numbers
    - 'examples': list of first 10 examples found
    """
    def is_odd_digit(d):
        return d in {'1', '3', '5', '7', '9'}

    def starts_and_ends_with_odd(n):
        if n <= 10:
            return False
        s = str(n)
        return is_odd_digit(s[0]) and is_odd_digit(s[-1])

    # Count numbers and collect examples
    count = 0
    examples = []

    # Start from 11 since we need numbers > 10
    for num in range(11, 1000000):
        if starts_and_ends_with_odd(num):
            count += 1
            if len(examples) < 10:
                examples.append(num)

    return {
        'count': count,
        'examples': examples
    }

if __name__ == "__main__":
