def count_palindromes_by_parity(n):
    """
    Count palindromes from 1 to n by parity (even/odd).
    Returns a dictionary with 'even' and 'odd' counts.
    """
    def is_palindrome(num):
        s = str(num)
        return s == s[::-1]

    def classify(num):
        return 'even' if num % 2 == 0 else 'odd'

    counts = {'even': 0, 'odd': 0}
    for i in range(1, n + 1):
        if is_palindrome(i):
            counts[classify(i)] += 1
    return counts

